host_operator_src="""
#include "interpolate_dynamic_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    InterpolateDynamicCustomTilingData tiling;

    const gert::Shape* in_shape = context->GetInputShape(0);
    // Expect NCHW
    uint32_t n = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(0));
    uint32_t c = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(1));
    uint32_t hin = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(2));
    uint32_t win = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(3));

    const gert::Shape* out_shape = context->GetOutputShape(0);
    uint32_t hout = static_cast<uint32_t>(out_shape->GetOriginShape().GetDim(2));
    uint32_t wout = static_cast<uint32_t>(out_shape->GetOriginShape().GetDim(3));

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_n(n);
    tiling.set_c(c);
    tiling.set_hin(hin);
    tiling.set_win(win);
    tiling.set_hout(hout);
    tiling.set_wout(wout);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // 这里假设前端已根据 size 设置了输出形状，此处保持输出形状不变
    const gert::Shape* out_shape = context->GetOutputShape(0);
    gert::Shape* y_shape = context->GetOutputShape(0);
    *y_shape = *out_shape;
    return GRAPH_SUCCESS;
}
static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
}

